-- Web push: everyone who allowed notifications is told the moment a table opens.
--
-- Flow: games INSERT -> trigger -> pg_net POST to the notify-table-opened Edge Function (shared
-- secret in a header) -> the function sends Web Push to every stored subscription except the opener's.
--
-- Secrets never live in this repo: the shared secret is generated here in the database, and the VAPID
-- key pair is generated by the Edge Function on first use. Both sit in push_config, which no client
-- role can read. After running this migration on a new project, also insert
--   ('function_url', 'https://<project-ref>.supabase.co/functions/v1/notify-table-opened')
-- into push_config and deploy supabase/functions/notify-table-opened.

create extension if not exists pg_net with schema extensions;

create table public.push_config (
  key text primary key,
  value text not null
);
alter table public.push_config enable row level security;
revoke all on public.push_config from anon, authenticated;

insert into public.push_config (key, value)
values ('trigger_secret', encode(extensions.gen_random_bytes(24), 'hex'))
on conflict (key) do nothing;

create table public.push_subscriptions (
  endpoint text primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  p256dh text not null,
  auth text not null,
  created_at timestamptz not null default now()
);
create index push_subscriptions_user_idx on public.push_subscriptions (user_id);
alter table public.push_subscriptions enable row level security;
revoke all on public.push_subscriptions from anon, authenticated;

-- The VAPID public key is not secret; the client needs it to subscribe.
create function public.push_public_key()
returns text language sql stable security definer set search_path = '' as $$
  select c.value from public.push_config c where c.key = 'vapid_public';
$$;

create function public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = 'PT401';
  end if;
  insert into public.push_subscriptions (endpoint, user_id, p256dh, auth)
  values (p_endpoint, auth.uid(), p_p256dh, p_auth)
  on conflict (endpoint) do update
    set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth;
end;
$$;

create function public.delete_push_subscription(p_endpoint text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then
    raise exception 'NOT_AUTHENTICATED' using errcode = 'PT401';
  end if;
  delete from public.push_subscriptions where endpoint = p_endpoint and user_id = auth.uid();
end;
$$;

-- Fires after a game is created. Never blocks opening a table: any failure is swallowed.
create function public.notify_table_opened()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_url text;
  v_secret text;
begin
  if new.status <> 'open' then
    return null;
  end if;
  begin
    select c.value into v_url from public.push_config c where c.key = 'function_url';
    select c.value into v_secret from public.push_config c where c.key = 'trigger_secret';
    if v_url is not null and v_secret is not null then
      perform net.http_post(
        url := v_url,
        headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', v_secret),
        body := jsonb_build_object('game_id', new.id)
      );
    end if;
  exception when others then
    null;
  end;
  return null;
end;
$$;

create trigger games_notify_open
  after insert on public.games
  for each row execute function public.notify_table_opened();

revoke all on function
  public.push_public_key(), public.save_push_subscription(text, text, text),
  public.delete_push_subscription(text), public.notify_table_opened()
  from public, anon, authenticated;
grant execute on function
  public.push_public_key(), public.save_push_subscription(text, text, text),
  public.delete_push_subscription(text)
  to authenticated;
